mapper.insert:
insert into sms_verification_codes (
    phone_hash, purpose, code_hash, request_ip, status, attempt_count,
    send_bucket, expires_time
) values (
    #{phoneHash}, #{purpose}, #{codeHash}, #{requestIp}, #{status}, #{attemptCount},
    #{sendBucket}, #{expiresTime}
)

mapper.select:
select count(1)
from sms_verification_codes
where phone_hash = #{phoneHash}
  and purpose = #{purpose}
  and status in ('PENDING', 'SENT')
  and create_time >= #{fromTime}

select count(1)
from sms_verification_codes
where request_ip = #{requestIp}
  and status in ('PENDING', 'SENT')
  and create_time >= #{fromTime}

select id, phone_hash, purpose, code_hash, request_ip, status, attempt_count,
       send_bucket, expires_time, consumed_time, create_time, update_time
from sms_verification_codes
where phone_hash = #{phoneHash}
  and purpose = #{purpose}
  and status = 'SENT'
  and expires_time > #{now}
order by id desc
limit 1
for update

mapper.delete:
delete from sms_verification_codes
where create_time < #{cutoff}
limit #{limit}
